package org.example.user.model;

import java.time.Instant;

import org.example.user.Role;
import org.example.user.User;

/**
 * A user as returned by the API. Neither the password nor its hash ever leaves the server.
 *
 * @param id        generated by the database
 * @param email     the normalized address
 * @param createdAt moment the user was created (ISO-8601, UTC, microseconds)
 */
public record UserResponse(Long id, String email, Role role, Instant createdAt) {

    public static UserResponse of(User user) {
        return new UserResponse(user.getId(), user.getEmail(), user.getRole(), user.getCreatedAt());
    }
}
